 4	/**
 5	 * Locate the `Claim` argument in a parsed `sendSnapshot` call.
 6	 *
 7	 * The argument list is route-dependent:
 8	 *   arbToEth              `sendSnapshot(uint256 _epoch, Claim _claim)`
 9	 *   arbToGnosis/gnosisToArb `sendSnapshot(uint256 _epoch, uint256 _gasLimit, Claim _claim)`
10	 *
11	 * so a hardcoded index is wrong on one of them. The claim is the only
12	 * tuple-typed parameter in every variant, so the index is derived from the
13	 * parsed function fragment rather than from the route - no chainId plumbing,
14	 * and a future signature change cannot silently reintroduce the bug.
15	 *
16	 * @returns The index of the tuple parameter, or -1 if the fragment has none
17	 */
18	const claimArgIndex = (fragment: any): number => {
19	  const inputs = fragment?.inputs ?? [];
20	  // Searched from the end: the claim is always the last parameter.
21	  for (let i = inputs.length - 1; i >= 0; i--) {
22	    const input = inputs[i];
23	    if (input?.baseType === "tuple" || input?.type === "tuple") return i;
24	  }
25	  return -1;
26	};
