29	 * Recompute the claim hash carried by a `sendSnapshot` transaction.
30	 *
31	 * Reading the wrong argument hashes the gas limit instead of the claim, so the
32	 * result never matches the outbox's `claimHashes[epoch]` and a snapshot that was
33	 * in fact sent looks unsent forever - the challenger then keeps re-sending it.
34	 *
35	 * @returns The claim hash the transaction carries, or null if it cannot be read
36	 */
37	const getSentSnapshotData = async (
38	  txHash: string,
39	  provider: JsonRpcProvider,
40	  inboxInterface: any
41	): Promise<string | null> => {
42	  const tx = await provider.getTransaction(txHash);
43	  if (!tx) return null;
44	
45	  // Parse the transaction calldata to identify function + args
46	  const parsed = inboxInterface.parseTransaction({ data: tx.data });
47	  // ethers v6 returns null for calldata no fragment matches; never throw here,
48	  // an unparsable tx is a "not sent" answer, not a dead route task.
49	  if (!parsed) return null;
50	  const index = claimArgIndex(parsed.fragment);
51	  if (index === -1) return null;
52	  const claimTuple = parsed.args[index] as unknown as ClaimStruct;
53	  const expectedClaimHash = hashClaim(claimTuple);
